{
  "name": "horology",
  "version": "0.2.1",
  "description": "opencode plugin: schedule prompts and slash-commands into a live opencode session using system-native timers (systemd user timers), so recurring jobs and one-shot reminders survive restarts and land in the right session.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "scheduler",
    "cron",
    "systemd",
    "timer"
  ],
  "license": "MIT",
  "author": "Quintin De Kok",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/SynthSwarm/horology.git",
    "directory": "opencode-plugin"
  },
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "prepublishOnly": "npm run build"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.17.13",
    "@types/node": "^20.19.43",
    "typescript": "^5.6.0"
  },
  "dependencies": {
    "zod": "^4.1.8"
  },
  "engines": {
    "node": ">=20"
  }
}
